<?php
require __DIR__.'/includes/bootstrap.php'; require_login();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='add'){$name=trim($_POST['name']??'');$target=parse_amount_ro($_POST['target_amount']??'0');if($name===''||$target<=0)throw new RuntimeException('Completează denumirea și obiectivul.');$s=$pdo->prepare('INSERT INTO savings_goals(name,target_amount,active) VALUES(?,?,1)');$s->execute([$name,$target]);$message='Obiectivul a fost creat.';}
 if($action==='contribute'){$id=(int)($_POST['id']??0);$amount=parse_amount_ro($_POST['amount']??'0');$date=parse_ro_date($_POST['date']??'',date('Y-m-d'));if($amount<=0||!$date)throw new RuntimeException('Completează o sumă și o dată valide.');$s=$pdo->prepare('INSERT INTO savings_contributions(goal_id,amount,contribution_date,created_by_member_id) VALUES(?,?,?,?)');$s->execute([$id,$amount,$date,current_member_id()]); log_activity($pdo,'savings_added','savings_goal',$id,'Economii · '.money_ro($amount)); $message='Suma a fost pusă deoparte. Nu este tratată ca o cheltuială.';}
 if($action==='toggle'){$id=(int)($_POST['id']??0);$s=$pdo->prepare('UPDATE savings_goals SET active=IF(active=1,0,1) WHERE id=?');$s->execute([$id]);$message='Obiectivul a fost actualizat.';}
}catch(Throwable $e){$error=$e->getMessage();}}
$goals=$pdo->query("SELECT g.*,COALESCE(SUM(sc.amount),0) saved FROM savings_goals g LEFT JOIN savings_contributions sc ON sc.goal_id=g.id GROUP BY g.id ORDER BY g.active DESC,g.id DESC")->fetchAll();$savedMonth=month_savings($pdo,date('Y-m'));
$pageTitle='Economii';$active='money';require __DIR__.'/includes/layout_top.php';
?>
<?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<section class="savings-hero"><div class="savings-hero-icon"><?=icon('piggy')?></div><div><span>Pus deoparte luna aceasta</span><strong><?=money_ro($savedMonth)?></strong><small>Economiile sunt separate de cheltuieli, ca statisticile să rămână corecte.</small></div></section>
<section class="action-head"><div><span class="eyebrow">Obiective</span><h2>Pentru ce economisești?</h2></div><button class="btn primary compact" type="button" data-toggle-target="#goalAddCard"><?=icon('plus')?> Adaugă</button></section>
<section class="settings-card" id="goalAddCard" hidden><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Denumire<div class="input-wrap"><?=icon('target')?><input name="name" required placeholder="Ex: Fond de urgență, Vacanță"></div></label><label>Țintă<div class="input-wrap money-input"><?=icon('wallet')?><input name="target_amount" inputmode="decimal" required placeholder="30.000"><span>lei</span></div></label><button class="btn primary wide">Creează obiectivul</button></form></section>
<div class="goal-list"><?php if(!$goals):?><div class="empty-card">Creează un obiectiv și notează doar când muți efectiv bani în economii.</div><?php endif;?><?php foreach($goals as $g):$pct=$g['target_amount']>0?min(100,round($g['saved']/$g['target_amount']*100)):0;?>
<article class="goal-card <?=$g['active']?'':'is-paused'?>"><div class="goal-head"><div><strong><?=e($g['name'])?></strong><span><?=money_ro($g['saved'])?> din <?=money_ro($g['target_amount'])?></span></div><b><?=$pct?>%</b></div><div class="progress savings"><i style="width:<?=$pct?>%"></i></div>
<?php if($g['active']):?><form method="post" class="goal-contribute"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="contribute"><input type="hidden" name="id" value="<?=$g['id']?>"><input name="amount" inputmode="decimal" placeholder="Sumă" required><input class="ro-date" name="date" inputmode="numeric" maxlength="10" value="<?=date('d.m.Y')?>" required><button class="btn soft compact">+ Pune deoparte</button></form><?php endif;?>
<form method="post" class="goal-toggle"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$g['id']?>"><button class="text-btn"><?=$g['active']?'Arhivează':'Reactivează'?></button></form></article><?php endforeach;?></div>
<?php require __DIR__.'/includes/layout_bottom.php'; ?>
